        ContentType.Xml => "xml",
        ContentType.Toml => "toml",
        ContentType.Markdown => "markdown",
        ContentType.SourceCode => "code",
        ContentType.DirectoryListing => "listing",
        ContentType.ShellTranscript => "shell",
        _ => "unknown",
